# ============================================================
#  BJH Dashboard - patch_V666.ps1
#  base V654.x .. V666.x  ->  V666.0
#
#  Ships only the files that changed. Untouched files are verified by SHA256.
#
#  NEW in V666
#   Every dataset carries a URL, and each points at a different endpoint:
#     SC_BILL     -> EDIT_SC              SpareParts -> EDIT_SPARE_PART
#     Quotation   -> EDIT_QUOTATION       SERVICE_JOB -> EDITJOB
#   A row must use its own URL, never another table's.
#   One shared window._sfLink() helper is now used everywhere: the main
#   orders table (SP rows link to EDIT_SPARE_PART), SC/SP Quotation,
#   Contract Monitor and two more tables. No URL means plain text, never
#   a dead link.
#
#  HOW TO RUN - save the file, do not paste its contents:
#     cd C:\bjh-dashboard
#     .\start.ps1
#     & .\Deploy\patch_V666.ps1
# ============================================================
$ErrorActionPreference = 'Stop'
$ROOT = 'C:\bjh-dashboard'
Set-Location $ROOT
try { Start-Transcript -Path (Join-Path $ROOT 'last.log') -Force -Append | Out-Null } catch {}

$NEWVER = 'V666.0'
$STAMP  = Get-Date -Format 'yyyyMMdd_HHmmss'
$MSG    = 'V666 SmartFlow links on every page, SP rows point at EDIT_SPARE_PART'

function Say($t, $c) { Write-Host $t -ForegroundColor $c }

$ovPath = Join-Path $ROOT 'overrides.html'
if (-not (Test-Path $ovPath)) { Say 'ABORT: overrides.html not found' Red; exit 1 }
$m = [regex]::Match([IO.File]::ReadAllText($ovPath), "_BUILD_VER\s*=\s*'([^']+)'")
if (-not $m.Success) { Say 'ABORT: _BUILD_VER not found' Red; exit 1 }
$curVer = $m.Groups[1].Value
Say ("current _BUILD_VER : " + $curVer) Yellow
if ($curVer -notmatch '^V6(5[4-9]|6[0-6])\.') {
  Say ("ABORT: base must be V654.x .. V666.x but found " + $curVer) Red
  exit 1
}

# ---------- untouched files: SHA check only ----------
function Check-Same {
  param([string]$Name, [string]$Sha)
  $fp = Join-Path $ROOT $Name
  if (-not (Test-Path $fp)) {
    Say ("ABORT: " + $Name + " is missing") Red
    Say '       ask for a full patch' Yellow
    exit 1
  }
  $got = (Get-FileHash -Path $fp -Algorithm SHA256).Hash.ToLower()
  if ($got -ne $Sha) {
    Say ("ABORT: " + $Name + " does not match the base this patch was built on") Red
    Say '       your copy has changes this patch does not know about.' Yellow
    Say '       nothing was written - ask for a full patch.' Yellow
    exit 1
  }
}

