Write-Host ''
function Write-Payload {
  param([string]$Name, [string]$B64, [string]$Sha, [int]$Size)
  $target = Join-Path $ROOT $Name
  if (Test-Path $target) { Copy-Item $target ($target + '.bak_' + $STAMP) -Force }
  $bytes = [Convert]::FromBase64String(($B64 -replace '\s', ''))
  $ms  = New-Object System.IO.MemoryStream(, $bytes)
  $gz  = New-Object System.IO.Compression.GZipStream($ms, [IO.Compression.CompressionMode]::Decompress)
  $out = New-Object System.IO.MemoryStream
  $gz.CopyTo($out); $gz.Dispose(); $ms.Dispose()
  $data = $out.ToArray(); $out.Dispose()
  if ($data.Length -ne $Size) { Say ("ABORT: size mismatch " + $Name) Red; exit 1 }
  [IO.File]::WriteAllBytes($target, $data)
  $got = (Get-FileHash -Path $target -Algorithm SHA256).Hash.ToLower()
  if ($got -ne $Sha) {
    Say ("ABORT: sha256 mismatch " + $Name) Red
    if (Test-Path ($target + '.bak_' + $STAMP)) { Copy-Item ($target + '.bak_' + $STAMP) $target -Force }
    exit 1
  }
  Say ("  written  " + $Name.PadRight(22) + $Size + " bytes  sha ok") Green
}

