Write-Host ''
Say 'untracking backup files (kept on disk)...' Cyan
git rm --cached --ignore-unmatch -q -- *.bak_* *.broken_* last.log 2>$null

Write-Host ''
Say 'clasp push...' Cyan
clasp push
if ($LASTEXITCODE -ne 0) { Say 'ABORT: clasp push failed - run .\start.ps1 first?' Red; exit 1 }

Say 'create deployment...' Cyan
clasp create-deployment -i AKfycbzO7LW1DPUOzosAxpZsJPvX8PoW4eJ8rDHuZI-GXwHpT9yXDERnrEdPVvdOoffQLVF-kw -d $MSG
if ($LASTEXITCODE -ne 0) { Say 'WARN: create-deployment failed - deploy manually' Yellow }

Say 'git commit + push...' Cyan
git add -A
git commit -m $MSG
git push origin main
if ($LASTEXITCODE -ne 0) { Say 'WARN: git push failed' Yellow }

Write-Host ''
Say ('DONE : ' + $NEWVER) Green
Write-Host ''
Say 'NEXT STEPS' Yellow
Say '  1. Ctrl+Shift+R' Yellow
Say '  2. Config > Load SR Job  (pulls master by itself if needed)' Yellow
Say '  3. Load Data' Yellow
Say '  5. click a quotation number - SmartFlow opens in a new tab' Yellow
Say '  6. send bjh_job.json.gz over so the SR fields can be reviewed' Yellow
Say '     status picker and the breakdown popup should all follow' Yellow
try { Stop-Transcript | Out-Null } catch {}
